import base64
import re

with open('audio.wav', 'rb') as f:
    data = f.read()

b64_pattern = rb'[A-Za-z0-9+/]{4,}={0,2}'
matches = re.findall(b64_pattern, data)

print(f"Total {len(matches)} chaînes Base64:\n")

for i, m in enumerate(matches):
    try:
        padded = m + b'=' * (4 - len(m) % 4) if len(m) % 4 else m
        decoded = base64.b64decode(padded)
        # Afficher la chaîne et son décodage
        try:
            text = decoded.decode('ascii', errors='replace')
            printable = all(c.isprintable() or c in '\n\r\t' for c in text)
            if printable:
                print(f"{i:2}: {m.decode('ascii'):20} -> {repr(text)}")
            else:
                print(f"{i:2}: {m.decode('ascii'):20} -> [binaire] {decoded[:20].hex()}...")
        except:
            print(f"{i:2}: {m.decode('ascii'):20} -> [binaire] {decoded[:20].hex()}...")
    except Exception as e:
        print(f"{i:2}: {m.decode('ascii'):20} -> ERROR: {e}")

# Analysons la relation entre '2_5t3@1_' et 'csaw{...}'
# Peut-être que chaque caractère est XORé avec quelque chose

target = "2_5t3@1_"
# Le format flag est csaw{...} donc peut-être que 2_5t3@1_ est le contenu entre les accolades
# Ou peut-être que c'est une substitution

# Essayons de voir si c'est un décalage simple (ROT)
for shift in range(26):
    result = ""
    for c in target:
        if c.isalpha():
            base = ord('a') if c.islower() else ord('A')
            result += chr((ord(c) - base + shift) % 26 + base)
        else:
            result += c
    print(f"ROT{shift}: {result}")

print("\n---")
# Essayons XOR avec des clés simples
for key in range(256):
    result = ""
    for c in target:
        result += chr(ord(c) ^ key)
    if result.startswith('c') and 'saw' in result:
        print(f"XOR avec {key}: {repr(result)}")
